var e=`2026-10-11`,t={law:`Derecho aéreo`,met:`Meteorología`,nav:`Navegación`,perf:`Performance y planificación`,pof:`Principios de vuelo`,agk:`Conocimiento general de la aeronave`,hp:`Factores humanos`,ops:`Procedimientos operacionales`,com:`Comunicaciones`},n=JSON.parse(`{"q001":{"q":"¿Cuánto tiempo es válida una habilitación de clase SEP (tierra)?","options":["12 meses","24 meses","36 meses","Ilimitada"],"explain":"Las habilitaciones de clase monomotor de un solo piloto son válidas 24 meses.","hint":"Piensa en el ritmo habitual de dos años de las habilitaciones de clase."},"q002":{"q":"Para revalidar una habilitación SEP por experiencia, ¿cuántas horas de vuelo necesitas en los 12 meses anteriores al vencimiento?","options":["6 h","10 h","12 h","15 h"],"explain":"12 h en la clase, incluidas 6 h como PIC, 12 despegues y 12 aterrizajes, más un vuelo de entrenamiento de al menos 1 h con un instructor.","hint":"De media, una hora al mes en el último año."},"q003":{"q":"De esas horas para la revalidación SEP por experiencia, ¿cuántas deben volarse como PIC?","options":["3 h","6 h","8 h","12 h"],"explain":"Al menos 6 de las 12 horas deben ser tiempo PIC.","hint":"La mitad de las horas exigidas."},"q004":{"q":"¿Cuántos despegues y aterrizajes se requieren para la revalidación SEP por experiencia?","options":["3 y 3","6 y 6","12 y 12","Sin mínimo"],"explain":"12 despegues y 12 aterrizajes en los 12 meses anteriores al vencimiento.","hint":"De media, un despegue y un aterrizaje al mes."},"q005":{"q":"¿Qué se requiere además de las horas y los aterrizajes para la revalidación SEP por experiencia?","options":["Un examen escrito","Un vuelo de entrenamiento de al menos 1 h con un instructor","Un vuelo nocturno","Un vuelo al extranjero"],"explain":"Un vuelo de entrenamiento de refresco de al menos 1 hora con un instructor de vuelo (o instructor de habilitación de clase).","hint":"Algo que haces junto con un instructor de vuelo."},"q006":{"q":"Antes de llevar pasajeros como PIC, ¿qué experiencia reciente necesitas?","options":["1 despegue y 1 aterrizaje en los últimos 30 días","3 despegues y 3 aterrizajes en los últimos 90 días en el mismo tipo o clase","3 horas en los últimos 90 días","5 despegues y 5 aterrizajes en los últimos 6 meses"],"explain":"3 despegues, aproximaciones y aterrizajes en los 90 días anteriores en una aeronave del mismo tipo o clase (o en un FFS).","hint":"Tres de cada, en unos tres meses."},"q007":{"q":"Para llevar pasajeros de noche como PIC (sin habilitación de vuelo instrumental), al menos uno de los 3 despegues y aterrizajes recientes debe haber sido de noche.","explain":"Sin una IR válida, al menos 1 de los 3 despegues y aterrizajes de los últimos 90 días debe haber sido de noche.","hint":"¿Qué cambia de noche respecto al día para los pasajeros?"},"q008":{"q":"Un piloto de 30 años obtiene un certificado médico de clase 2. ¿Cuánto tiempo es válido?","options":["12 meses","24 meses","60 meses","Ilimitado"],"explain":"Clase 2: 60 meses hasta los 40 años, 24 meses de 40 a 50, 12 meses a partir de los 50. (Un certificado emitido antes de los 40 vence como muy tarde a los 42.)","hint":"Los pilotos jóvenes tienen la validez más larga: cinco años."},"q009":{"q":"¿Cuánto tiempo es válido un certificado médico de clase 2 para un piloto de 45 años?","options":["12 meses","24 meses","36 meses","60 meses"],"explain":"Entre los 40 y los 50 años: 24 meses.","hint":"Entre los 40 y los 50 la validez se reduce a dos años."},"q010":{"q":"¿Cuánto tiempo es válido un certificado médico de clase 2 para un piloto de 52 años?","options":["6 meses","12 meses","24 meses","60 meses"],"explain":"A partir de los 50 años: 12 meses.","hint":"A partir de los 50 vas al médico examinador cada año."},"q011":{"q":"La competencia lingüística de nivel 4 (operacional) es válida durante:","options":["2 años","4 años","6 años","Ilimitada"],"explain":"Nivel 4: 4 años, nivel 5: 6 años, nivel 6: no requiere reevaluación.","hint":"El nivel 4 es el mínimo operacional: necesita la comprobación más frecuente."},"q012":{"q":"La competencia lingüística de nivel 5 (avanzado) es válida durante:","options":["4 años","5 años","6 años","Ilimitada"],"explain":"El nivel 5 es válido 6 años.","hint":"Nivel más alto = validez más larga; el nivel 6 no caduca nunca."},"q013":{"q":"¿Tiene la PPL(A) en sí misma una fecha de caducidad?","options":["Sí, 5 años","Sí, 10 años","No – pero las habilitaciones y el certificado médico deben ser válidos para usarla","Sí, caduca con el certificado médico"],"explain":"La licencia EASA no tiene fecha de caducidad. Para ejercer sus atribuciones, la habilitación de clase y el certificado médico deben ser válidos.","hint":"¿Qué renuevas en realidad: la licencia o lo que contiene?"},"q014":{"q":"¿Qué documentos debes llevar contigo como piloto al volar?","options":["Tu licencia","Tu certificado médico válido","Un documento de identidad con foto","Tu libro de vuelo"],"explain":"Licencia, certificado médico y documento de identidad con foto deben llevarse. El libro de vuelo no tiene que ir a bordo.","hint":"Piensa: quién eres, qué puedes volar y si estás apto médicamente."},"q015":{"q":"En un vuelo privado de costes compartidos, ¿entre cuántas personas como máximo (incluido el piloto) pueden repartirse los costes directos?","options":["2","4","6","9"],"explain":"Vuelos de costes compartidos entre particulares: costes directos compartidos por todos los ocupantes incluido el piloto, máximo 6 personas.","hint":"Tantos como los asientos de muchas avionetas monomotor pequeñas."},"q016":{"q":"¿Qué código de transpondedor indica fallo de radio?","options":["7000","7500","7600","7700"],"explain":"7600 = fallo de radio, 7700 = emergencia, 7500 = interferencia ilícita.","hint":"Regla mnemotécnica inglesa: «Seven-six – radio fix» (radio averiada)."},"q017":{"q":"¿Qué código de transpondedor indica una emergencia?","options":["7000","7500","7600","7700"],"explain":"7700 = emergencia.","hint":"Regla mnemotécnica inglesa: «Seven-seven – going to heaven» (emergencia)."},"q141":{"q":"¿Qué código de transpondedor indica interferencia ilícita (secuestro)?","options":["7000","7500","7600","7700"],"explain":"7500 = interferencia ilícita, 7600 = fallo de radio, 7700 = emergencia.","hint":"Regla mnemotécnica inglesa: «Seven-five – man with a knife» (hombre con un cuchillo)."},"q018":{"q":"¿Cuál es el código VFR estándar en Suiza y en la mayor parte de Europa?","options":["2000","7000","1200","0000"],"explain":"7000 es el código VFR en Europa (1200 se usa en EE. UU.).","hint":"El código VFR en EE. UU. es 1200; en Europa es otro."},"q019":{"q":"Dos aeronaves de la misma categoría convergen aproximadamente al mismo nivel. ¿Quién cede el paso?","options":["La más rápida","La que tiene a la otra a su derecha","La que tiene a la otra a su izquierda","La más alta"],"explain":"La aeronave que tiene a la otra a su derecha cede el paso.","hint":"Como en muchos cruces de carretera: prioridad a la derecha."},"q020":{"q":"Dos aeronaves se aproximan de frente. ¿Qué hacen ambas?","options":["Ambas viran a la izquierda","Ambas viran a la derecha","Ambas ascienden","La más baja desciende"],"explain":"Ambas cambian el rumbo hacia la derecha.","hint":"La misma idea que dos barcos que se cruzan: ambos giran hacia el mismo lado."},"q021":{"q":"Estás adelantando a otra aeronave. ¿Cómo la adelantas?","options":["Por su izquierda","Por su derecha, cambiando el rumbo hacia la derecha","Por encima","Por debajo"],"explain":"La aeronave que adelanta se aparta cambiando el rumbo hacia la derecha.","hint":"Quien adelanta cede el paso y pasa por el mismo lado que en la regla de frente."},"q022":{"q":"Dos aeronaves están en final para aterrizar. ¿Cuál tiene prioridad?","options":["La más alta","La más rápida","La más baja","La que llamó primero"],"explain":"La aeronave más baja tiene prioridad, pero no debe cortar ni adelantar a otra en final.","hint":"El avión más cerca del suelo tiene menos margen de maniobra."},"q023":{"q":"Señal luminosa de la torre a una aeronave en vuelo: verde fija.","options":["Autorizado a aterrizar","Regrese para aterrizar","Ceda el paso, siga en circuito","Aeródromo inseguro, no aterrice"],"explain":"Verde fija en vuelo = autorizado a aterrizar.","hint":"Verde y fijo = adelante."},"q024":{"q":"Señal luminosa a una aeronave en vuelo: roja intermitente.","options":["Autorizado a aterrizar","Aeródromo inseguro, no aterrice","Ceda el paso, siga en circuito","Regrese para aterrizar"],"explain":"Roja intermitente en vuelo = aeródromo inseguro, no aterrice.","hint":"Rojo intermitente en vuelo = el problema es el propio aeródromo."},"q025":{"q":"Señal luminosa a una aeronave en vuelo: roja fija.","options":["Ceda el paso a otras aeronaves y siga en circuito","No aterrice","Autorizado a aterrizar","Aterrice inmediatamente"],"explain":"Roja fija en vuelo = ceda el paso a otras aeronaves y siga en circuito.","hint":"Rojo fijo en vuelo = tú no, ahora no: sigue en circuito."},"q026":{"q":"Señal luminosa a una aeronave en tierra: blanca intermitente.","options":["Autorizado a rodar","Deténgase","Regrese al punto de partida en el aeródromo","Deje libre el área de aterrizaje"],"explain":"Blanca intermitente en tierra = regrese al punto de partida en el aeródromo.","hint":"Blanco intermitente en tierra = vuelve por donde viniste."},"q027":{"q":"Señal luminosa a una aeronave en tierra: verde intermitente.","options":["Autorizado a despegar","Autorizado a rodar","Deténgase","Regrese al punto de partida"],"explain":"Verde intermitente en tierra = autorizado a rodar.","hint":"En tierra, el verde intermitente te permite moverte."},"q028":{"q":"Altura mínima sobre zonas densamente pobladas de ciudades, pueblos o asentamientos (SERA, VFR):","options":["500 ft sobre el obstáculo más alto en 150 m","1000 ft sobre el obstáculo más alto en 600 m","1500 ft sobre el suelo","2000 ft sobre el obstáculo más alto en 1 km"],"explain":"1000 ft sobre el obstáculo más alto en un radio de 600 m de la aeronave. Excepto en despegue y aterrizaje.","hint":"Más altura, mayor radio sobre zonas pobladas."},"q029":{"q":"Altura mínima en otras zonas (no densamente pobladas), VFR:","options":["300 ft sobre el suelo o el agua","500 ft sobre el suelo o el agua","1000 ft sobre el suelo","Sin mínimo"],"explain":"500 ft sobre el suelo o el agua, o 500 ft sobre el obstáculo más alto en 150 m. Excepto en despegue y aterrizaje.","hint":"La mitad del valor sobre zonas pobladas."},"q030":{"q":"Mínimos VMC en los espacios aéreos C, D y E por debajo de FL100:","options":["1,5 km de visibilidad, libre de nubes","5 km de visibilidad, 1500 m horizontal y 1000 ft vertical de las nubes","8 km de visibilidad, 1500 m y 1000 ft de las nubes","5 km de visibilidad, 300 m de las nubes"],"explain":"Por debajo de FL100: 5 km de visibilidad en vuelo, 1500 m horizontal y 1000 ft vertical de las nubes.","hint":"Recuerda 5 – 1500 – 1000 por debajo del FL100."},"q031":{"q":"Mínimos VMC en los espacios aéreos C, D y E en FL100 y por encima:","options":["5 km de visibilidad","8 km de visibilidad, 1500 m y 1000 ft de las nubes","10 km de visibilidad, libre de nubes","8 km de visibilidad, libre de nubes"],"explain":"En FL100 y por encima la visibilidad en vuelo aumenta a 8 km.","hint":"Más alto y más rápido: la visibilidad exigida aumenta."},"q032":{"q":"VMC estándar SERA en clase G a 3000 ft AMSL o por debajo (o 1000 ft sobre el terreno, lo que sea mayor):","options":["5 km de visibilidad, libre de nubes y con la superficie a la vista","1,5 km de visibilidad, 1000 ft de las nubes","8 km de visibilidad","Sin mínimo"],"explain":"5 km, libre de nubes y con la superficie a la vista. Los Estados pueden permitir menos visibilidad a baja velocidad – consulta las normas nacionales (AIP).","hint":"Bajo y lento en G: libre de nubes y con el suelo a la vista."},"q033":{"q":"Para entrar en VFR (sin VFR especial) en una zona de control o en el circuito de tránsito, el techo y la visibilidad en tierra mínimos son:","options":["1000 ft y 3 km","1500 ft y 5 km","2000 ft y 8 km","500 ft y 1,5 km"],"explain":"Techo de al menos 1500 ft y visibilidad en tierra de al menos 5 km.","hint":"La misma visibilidad que las VMC básicas y un techo de 1500 ft."},"q034":{"q":"¿Cuándo se requiere un plan de vuelo para un vuelo VFR?","options":["Para cada vuelo","Para vuelos que cruzan una frontera internacional","Solo para vuelos por encima de FL100","Solo de noche"],"explain":"Entre otros casos, se requiere un plan de vuelo para cualquier vuelo que cruce fronteras internacionales, salvo que los Estados afectados dispongan otra cosa.","hint":"Piensa en salir del país."},"q035":{"q":"Vuelo VFR a más de 3000 ft sobre el terreno, derrota magnética 070°. ¿Qué altitud de crucero es correcta?","options":["4000 ft","4500 ft","5500 ft","6000 ft"],"explain":"Derrota magnética 000°–179°: miles impares + 500 ft (3500, 5500, 7500 ft …). Por encima de la altitud de transición como niveles de vuelo (FL75, FL95 …).","hint":"Hacia el este (000°–179°) = miles impares + 500."},"q036":{"q":"Vuelo VFR a más de 3000 ft sobre el terreno, derrota magnética 250°. ¿Qué altitud de crucero es correcta?","options":["5500 ft","6500 ft","7500 ft","5000 ft"],"explain":"Derrota magnética 180°–359°: miles pares + 500 ft (4500, 6500, 8500 ft …). Por encima de la altitud de transición como niveles de vuelo.","hint":"Hacia el oeste (180°–359°) = miles pares + 500."},"q037":{"q":"¿Quién tiene la autoridad final sobre si un vuelo se realiza?","options":["La escuela de vuelo","El control de tránsito aéreo","El piloto al mando (PIC)","El propietario de la aeronave"],"explain":"El PIC es responsable de la operación y la seguridad de la aeronave y decide si se vuela.","hint":"¿Quién firma el vuelo y asume la responsabilidad?"},"q038":{"q":"Con la habilitación de clase SEP vencida pero con PPL y certificado médico válidos, todavía puedes volar solo como PIC en un avión SEP.","explain":"No. La habilitación de clase debe ser válida para actuar como PIC. Tras el vencimiento se necesita una verificación de competencia (y posiblemente entrenamiento).","hint":"Licencia, habilitación y certificado médico deben ser válidos al mismo tiempo."},"q039":{"q":"Temperatura ISA al nivel medio del mar:","options":["0 °C","10 °C","15 °C","20 °C"],"explain":"ISA en MSL: 15 °C, 1013,25 hPa.","hint":"Un día templado de primavera en la playa."},"q040":{"q":"Presión ISA al nivel medio del mar:","options":["1000 hPa","1013.25 hPa","1020 hPa","29.92 hPa"],"explain":"1013,25 hPa (= 29,92 inHg).","hint":"El reglaje altimétrico estándar."},"q041":{"q":"Gradiente térmico ISA en la troposfera:","options":["1 °C por cada 1000 ft","2 °C por cada 1000 ft","3 °C por cada 1000 ft","0,5 °C por cada 1000 ft"],"explain":"Unos 2 °C por cada 1000 ft (0,65 °C por cada 100 m).","hint":"Aproximadamente 0,65 °C cada 100 m."},"q042":{"q":"¿Cuál es la temperatura ISA a 5000 ft?","explain":"15 °C − 5 × 2 °C = 5 °C.","hint":"Resta 2 °C por cada 1000 ft a partir de 15 °C."},"q043":{"q":"Temperatura 20 °C, punto de rocío 12 °C. Estima la base de los cúmulos (ft sobre el suelo).","explain":"Diferencia × 400 ft: 8 × 400 = 3200 ft (o diferencia × 125 m).","hint":"Diferencia (T − Td) × 400 ft."},"q044":{"q":"Gradiente adiabático seco (aire no saturado que asciende):","options":["Unos 1 °C por cada 100 m","Unos 0,5 °C por cada 100 m","Unos 2 °C por cada 100 m","0 °C – la temperatura se mantiene"],"explain":"Unos 1 °C por cada 100 m (3 °C por cada 1000 ft). El aire saturado se enfría más despacio (unos 0,6 °C por cada 100 m).","hint":"El aire no saturado se enfría más rápido que el gradiente ISA."},"q045":{"q":"En un METAR, BKN significa:","options":["1–2 octas","3–4 octas","5–7 octas","8 octas"],"explain":"FEW 1–2, SCT 3–4, BKN 5–7, OVC 8 octas.","hint":"Broken = más de la mitad del cielo, pero no todo."},"q046":{"q":"CAVOK significa:","options":["Visibilidad ≥ 5 km, sin nubes por debajo de 3000 ft","Visibilidad ≥ 10 km, sin nubes por debajo de 5000 ft (o MSA si es mayor), sin CB/TCU, sin tiempo significativo","Cielo despejado, sin viento","Techo por encima de 1500 ft"],"explain":"Visibilidad de 10 km o más, sin nubes por debajo de 5000 ft o la altitud mínima de sector más alta, sin CB ni TCU, sin tiempo significativo.","hint":"Ceiling And Visibility OK: piensa en 10 km y 5000 ft."},"q047":{"q":"La dirección del viento en un METAR o TAF se refiere al:","options":["Norte magnético","Norte verdadero","Norte de cuadrícula","Rumbo de la pista"],"explain":"METAR/TAF: norte verdadero. Viento dado por la torre o el ATIS: magnético.","hint":"Los mensajes escritos usan una referencia; la información ATC hablada, otra."},"q048":{"q":"En un TAF, TEMPO significa:","options":["Un cambio permanente","Fluctuaciones temporales, cada una de menos de 1 hora y en total menos de la mitad del período","Una probabilidad del 30 %","El pronóstico queda cancelado"],"explain":"TEMPO: fluctuaciones temporales, cada una de menos de 1 h, en conjunto menos de la mitad del período.","hint":"Temporary: breve y no la mayor parte del tiempo."},"q049":{"q":"La niebla de radiación se forma típicamente con:","options":["Viento fuerte y cielo cubierto","Cielo despejado, viento flojo y alta humedad por la noche","El paso de un frente cálido","Tormentas"],"explain":"Noche despejada (el suelo se enfría por radiación), viento flojo y aire húmedo cerca del suelo.","hint":"El suelo tiene que enfriarse mucho durante la noche."},"q050":{"q":"¿Qué nube es típica de las ondas de montaña (p. ej. con foehn)?","options":["Cumulonimbo","Altocumulus lenticularis","Nimbostrato","Cirro"],"explain":"Las nubes lenticulares (ACSL) indican ondas estacionarias – espera turbulencia y rotores por debajo.","hint":"Con forma de lente o de ovni."},"q051":{"q":"El foehn en la vertiente norte de los Alpes trae:","options":["Aire frío y húmedo y niebla","Viento cálido, seco y racheado con turbulencia a sotavento","Solo tormentas","Condiciones de calma"],"explain":"Viento descendente cálido, seco, a menudo racheado a sotavento; fuerte turbulencia y rotores cerca de las montañas.","hint":"El aire se comprime y se calienta al descender por sotavento."},"q052":{"q":"Ordena las fases de una tormenta.","items":["Fase de cúmulo (desarrollo)","Fase de madurez","Fase de disipación"],"explain":"Fase de cúmulo (corrientes ascendentes) → fase de madurez (corrientes ascendentes y descendentes, fuerte precipitación, mayores peligros) → fase de disipación (corrientes descendentes).","hint":"Crecimiento – madurez – disipación."},"q053":{"q":"¿En qué fase de una tormenta son más fuertes las corrientes ascendentes y descendentes?","options":["Fase de cúmulo","Fase de madurez","Fase de disipación","Igual en todas"],"explain":"La fase de madurez comienza cuando la precipitación llega al suelo – máxima turbulencia, cizalladura, granizo y rayos.","hint":"Cuando la lluvia y el granizo empiezan a caer de la nube."},"q054":{"q":"Se acerca un frente cálido. Ordena las nubes en el orden en que las ves.","items":["Cirro","Cirrostrato","Altostrato","Nimbostrato"],"explain":"Cirro → cirrostrato (halo) → altostrato → nimbostrato con lluvia continua.","hint":"Primero las nubes altas, la nube de lluvia más baja al final."},"q055":{"q":"¿Cuándo es alto el riesgo de hielo en el carburador?","options":["Solo por debajo de 0 °C","Solo dentro de nubes","Con aire húmedo y temperaturas suaves (incluso por encima de +20 °C), sobre todo con poca potencia","Solo a plena potencia"],"explain":"La evaporación del combustible y el efecto Venturi enfrían el aire hasta 20–30 °C. Mayor riesgo con humedad alta, temperaturas suaves y poca potencia (descenso).","hint":"No es solo un problema de invierno."},"q056":{"q":"El punto de rocío es:","options":["La temperatura a la que el aire se satura al enfriarse","La temperatura de congelación del agua","La temperatura en la cima de las nubes","La temperatura del suelo por la noche"],"explain":"Al enfriar el aire hasta su punto de rocío se satura – se forman nubes o niebla.","hint":"Si el aire se enfría lo suficiente, no puede contener más agua."},"q057":{"q":"¿Qué peligros están asociados a un cumulonimbo?","options":["Turbulencia y cizalladura","Granizo y engelamiento","Rayos","Todos estos"],"explain":"Turbulencia fuerte, cizalladura, granizo, engelamiento, rayos y lluvia intensa. Mantente bien alejado (se recomienda a menudo al menos 10 NM).","hint":"Un CB tiene (casi) todo lo que no quieres."},"q142":{"q":"La bise en la meseta suiza es:","options":["Un viento cálido y seco descendente del sur","Un viento frío y seco del noreste, a menudo racheado y turbulento cerca del suelo","Una brisa marina","Una corriente descendente de tormenta"],"explain":"Aire continental frío fluye del noreste entre el Jura y los Alpes; se canaliza y es más fuerte en los estrechamientos como la región del lago Lemán. Cuenta con turbulencia a baja altura.","hint":"Viene del noreste y es fría."},"q143":{"q":"En invierno la meseta suiza suele estar bajo una capa gris (niebla alta) mientras en los Alpes hace sol. ¿Por qué?","options":["Un frente cálido","Una inversión térmica retiene debajo el aire frío y húmedo","El foehn","Baja presión sobre los Alpes"],"explain":"Con altas presiones el aire frío se acumula en la meseta; la inversión de encima impide la mezcla, debajo se forma un estrato bajo y encima está despejado.","hint":"El aire cálido se asienta sobre el aire frío."},"q144":{"q":"En el GAFOR suizo, ¿qué significa la categoría X?","options":["Abierto","Difícil","Crítico","Cerrado"],"explain":"Categorías GAFOR: O abierto – D difícil – M crítico – X cerrado (para la ruta, respecto a su altitud de referencia). Solo teoría – consulta siempre el pronóstico oficial actual.","hint":"O, D, M, X: del mejor al peor."},"q145":{"q":"La formación de hielo en la estructura es más probable:","options":["En aire claro por debajo de 0 °C","En nubes o lluvia a temperaturas entre unos 0 °C y −15 °C (gotas subfundidas)","Solo por debajo de −40 °C","Solo por encima de la isoterma de cero grados en aire claro"],"explain":"Las gotas de agua subfundidas se congelan al impactar. Lo más frecuente de 0 °C a unos −15 °C; la lluvia engelante es especialmente peligrosa. Conoce la isoterma de cero grados antes de cada vuelo.","hint":"El agua puede seguir líquida por debajo de 0 °C hasta que toca tu ala."},"q058":{"q":"¿Cuántos metros tiene 1 milla náutica?","explain":"1 NM = 1852 m = 1 minuto de latitud.","hint":"Un minuto de latitud."},"q059":{"q":"Velocidad sobre el suelo 100 kt, distancia 45 NM. ¿Cuántos minutos?","explain":"45 / 100 × 60 = 27 min.","hint":"Distancia ÷ velocidad × 60."},"q060":{"q":"Velocidad sobre el suelo 90 kt. ¿Qué distancia recorres en 40 minutos?","explain":"90 × 40 / 60 = 60 NM.","hint":"Velocidad × tiempo (en horas)."},"q061":{"q":"Rumbo verdadero 090°, variación 3° E. ¿Cuál es el rumbo magnético?","explain":"East is least: 090 − 3 = 087°.","hint":"Regla mnemotécnica inglesa: «East is least, west is best» (de verdadero a magnético)."},"q062":{"q":"Rumbo magnético 245°, variación 2° W. ¿Cuál es el rumbo verdadero?","explain":"West is best: MC = TC + W, por tanto TC = 245 − 2 = 243°.","hint":"De magnético a verdadero: invierte la regla."},"q063":{"q":"Regla 1 en 60: tras 30 NM estás 3 NM fuera de la derrota. ¿Cuál es el error de derrota en grados?","explain":"Error de derrota = desviación × 60 / distancia = 3 × 60 / 30 = 6°.","hint":"Desvío × 60 ÷ distancia recorrida."},"q064":{"q":"Las líneas que unen puntos de igual variación magnética se llaman:","options":["Isobaras","Isógonas","Solo agónicas","Isotermas"],"explain":"Isógonas (la agónica es la línea con variación 0°).","hint":"«Iso» = igual, «gono» = ángulo."},"q065":{"q":"El error de la brújula causado por campos magnéticos en la aeronave se llama:","options":["Variación","Desvío","Inclinación","Deriva"],"explain":"Desvío – indicado en la tarjeta de desvíos de la brújula.","hint":"La declinación viene de la Tierra; este error, del avión."},"q066":{"q":"Son las 14:30 hora local en Suiza en verano (CEST). ¿Qué hora es en UTC?","options":["12:30","13:30","14:30","15:30"],"explain":"Horario de verano CEST = UTC+2, horario de invierno CET = UTC+1.","hint":"El horario de verano suizo es UTC+2."},"q067":{"q":"5000 ft son aproximadamente ¿cuántos metros?","explain":"1 ft = 0,3048 m → 5000 × 0,3048 = 1524 m.","hint":"1 ft ≈ 0,3 m."},"q068":{"q":"En una carta 1:500 000, 1 cm equivale a:","options":["500 m","5 km","50 km","1 NM"],"explain":"1 cm × 500 000 = 5 km.","hint":"500 000 cm = 5000 m."},"q069":{"q":"Un minuto de latitud equivale a:","options":["1 km","1 NM","1 milla terrestre","60 NM"],"explain":"1′ de latitud = 1 NM (1° = 60 NM).","hint":"60 de ellos forman un grado, es decir, 60 NM."},"q070":{"q":"Un radial VOR es:","options":["La marcación magnética HACIA la estación","La marcación magnética DESDE la estación","La marcación verdadera hacia la estación","La distancia DME"],"explain":"Un radial es la marcación magnética desde la estación.","hint":"Los radiales salen de la estación como radios de una rueda."},"q071":{"q":"Corrección de viento: TAS 100 kt, componente de viento cruzado 10 kt. ¿Ángulo de corrección aproximado?","explain":"Deriva máxima ≈ viento cruzado × 60 / TAS = 10 × 60 / 100 = 6°.","hint":"Deriva máx. ≈ viento cruzado × 60 ÷ TAS."},"q072":{"q":"Elevación del aeródromo 1400 ft, QNH 1003 hPa. ¿Altitud de presión? (1 hPa ≈ 30 ft)","explain":"PA = elevación + (1013 − QNH) × 30 = 1400 + 10 × 30 = 1700 ft.","hint":"QNH inferior a 1013 → la altitud de presión es mayor. Unos 30 ft por hPa."},"q073":{"q":"Elevación del aeródromo 1300 ft, QNH 1013 hPa, OAT 30 °C. Estima la altitud de densidad.","explain":"ISA a 1300 ft ≈ 12,4 °C. DA ≈ PA + 120 × (OAT − ISA) = 1300 + 120 × 17,6 ≈ 3400 ft.","hint":"Primero halla la temperatura ISA a 1300 ft, luego 120 ft por °C sobre la ISA."},"q074":{"q":"Altitud de presión 5000 ft, OAT +25 °C. Estima la altitud de densidad.","explain":"ISA a 5000 ft = 5 °C, desviación +20 °C. DA ≈ 5000 + 120 × 20 = 7400 ft.","hint":"La ISA a 5000 ft es 5 °C."},"q075":{"q":"¿Qué significa una altitud de densidad alta para tu avión?","options":["Carrera de despegue más corta","Despegue más largo y menor régimen de ascenso","Más potencia del motor","Ningún efecto"],"explain":"Aire menos denso: menos potencia del motor, menos tracción de la hélice y sustentación – distancias de despegue y aterrizaje más largas, ascenso más débil.","hint":"Aire poco denso = menos potencia, menos sustentación."},"q076":{"q":"¿Cuáles de estos factores aumentan la distancia de despegue?","options":["Temperatura alta","Elevación alta del aeródromo","Viento de cola o hierba mojada","Todos estos"],"explain":"Calor, altitud, viento de cola, pendiente ascendente, hierba blanda o mojada, masa alta – cada uno añade distancia. Usa las tablas del AFM/POH.","hint":"Calor, altura, peso, viento de cola y suelo blando: todo juega en tu contra."},"q077":{"q":"Viento de 20 kt a 30° de la pista. ¿Componente de viento cruzado?","explain":"Viento cruzado = viento × sen(ángulo) = 20 × 0,5 = 10 kt.","hint":"sen 30° = 0,5."},"q078":{"q":"Viento de 20 kt a 60° de la pista. ¿Componente de viento cruzado?","explain":"20 × sen 60° ≈ 20 × 0,87 ≈ 17 kt.","hint":"sen 60° ≈ 0,87."},"q079":{"q":"Viento de 20 kt a 60° de la pista. ¿Componente de viento de cara?","explain":"Viento de cara = viento × cos(ángulo) = 20 × 0,5 = 10 kt.","hint":"cos 60° = 0,5."},"q080":{"q":"Consumo de 20 l/h. ¿Cuánto combustible para 1 h 45 min?","explain":"20 × 1,75 = 35 l.","hint":"1 h 45 min = 1,75 h."},"q081":{"q":"AVGAS 100LL, unos 0,72 kg/l. ¿Cuál es la masa de 100 litros?","explain":"100 × 0,72 = 72 kg.","hint":"Litros × densidad."},"q082":{"q":"10 galones US son ¿cuántos litros?","explain":"1 US gal ≈ 3,785 l → 37,9 l.","hint":"1 galón estadounidense ≈ 3,8 litros."},"q083":{"q":"Masa y centrado: avión 550 kg en brazo 0,40 m, piloto + pasajero 160 kg en 0,50 m, combustible 50 kg en 0,80 m. ¿Dónde está el CG (m)?","explain":"Momentos: 220 + 80 + 40 = 340 kg·m. Masa 760 kg. CG = 340 / 760 ≈ 0,447 m.","hint":"Centro de gravedad = momento total ÷ masa total (momento = masa × brazo)."},"q084":{"q":"Efecto de un CG cerca del límite trasero:","options":["Más estable, timón de profundidad más pesado","Menos estable, fuerzas ligeras en el timón de profundidad, salida de pérdida y barrena más difícil","Ningún efecto en el manejo","Solo carrera de despegue más larga"],"explain":"Un CG retrasado reduce la estabilidad longitudinal. Más allá del límite trasero, salir de una pérdida o barrena puede ser imposible.","hint":"Brazo de palanca corto para la cola = menos estabilidad."},"q085":{"q":"Vx es:","options":["Mejor régimen de ascenso","Mejor ángulo de ascenso","Mejor planeo","Velocidad a no exceder nunca"],"explain":"Vx = mejor ángulo (más altura por distancia, para obstáculos). Vy = mejor régimen (más altura por tiempo).","hint":"Regla mnemotécnica inglesa: X = extra empinado (ángulo), Y = yes, ascenso más rápido (régimen)."},"q086":{"q":"¿Cómo afecta una masa mayor al planeo?","options":["La distancia de planeo se reduce mucho","La velocidad de mejor planeo aumenta, la distancia de planeo se mantiene aproximadamente igual","La velocidad de mejor planeo disminuye","Ningún efecto"],"explain":"La relación de planeo máxima se mantiene aproximadamente igual, pero se alcanza a mayor velocidad.","hint":"La relación se mantiene; la velocidad cambia."},"q087":{"q":"Combustible de reserva final para un vuelo VFR diurno (no un vuelo local a la vista del aeródromo), Part-NCO:","options":["10 minutos","30 minutos","45 minutos","60 minutos"],"explain":"30 minutos a la altitud de crucero normal de día (10 minutos para vuelos locales a la vista del aeródromo). Es el mínimo legal – tu club, tu escuela de vuelo o el operador del avión puede exigir más (p. ej. 45 o 60 minutos). Se aplican sus normas. Planifica más de todos modos – las reservas son para lo inesperado.","hint":"Media hora, y comprueba lo que exige tu club."},"q088":{"q":"Un ala entra en pérdida cuando:","options":["La velocidad baja de un valor fijo","Se supera el ángulo de ataque crítico","Falla el motor","El avión es demasiado pesado"],"explain":"La pérdida depende del ángulo de ataque, no de la velocidad – puede ocurrir a cualquier velocidad y actitud.","hint":"Es cuestión de ángulo, no de velocidad."},"q089":{"q":"¿Cuál es el factor de carga en un viraje nivelado con 60° de alabeo?","explain":"n = 1 / cos 60° = 2.","hint":"n = 1 ÷ cos(alabeo)."},"q090":{"q":"Velocidad de pérdida con alas niveladas 50 kt. ¿Velocidad de pérdida aproximada en un viraje nivelado de 60°?","explain":"Vs aumenta con √n = √2 ≈ 1,41 → 50 × 1,41 ≈ 71 kt.","hint":"Multiplica por √(factor de carga)."},"q091":{"q":"Si duplicas la velocidad (todo lo demás igual), la sustentación pasa a ser:","options":["El doble","Cuatro veces mayor","La mitad","Igual"],"explain":"Sustentación ∝ v², por tanto velocidad doble = sustentación cuádruple.","hint":"La sustentación crece con el cuadrado de la velocidad."},"q092":{"q":"Extender los flaps:","options":["Aumenta la velocidad de pérdida","Reduce la velocidad de pérdida y aumenta la resistencia","Reduce la resistencia","No afecta a la velocidad de pérdida"],"explain":"Los flaps aumentan el C_L max (menor velocidad de pérdida) y añaden resistencia.","hint":"Más sustentación a baja velocidad, pero nada es gratis."},"q093":{"q":"La guiñada adversa al iniciar un viraje a la izquierda significa:","options":["El morro guiña a la izquierda","El morro guiña a la derecha, en contra del viraje","El avión asciende","El avión alabea a la derecha"],"explain":"El alerón que baja (ala derecha) genera más resistencia – el morro guiña en contra del viraje. Coordina con los pedales.","hint":"El alerón que baja produce más resistencia."},"q094":{"q":"Salida estándar de barrena (salvo que tu AFM diga otra cosa): ordena los pasos.","items":["Potencia a ralentí","Alerones neutros","Pedal contrario a fondo","Timón de profundidad adelante hasta que pare la rotación","Pedales neutros y salir del picado"],"explain":"PARE: Power a ralentí – Ailerons (alerones) neutros – Rudder (pedal) contrario – Elevator (profundidad) adelante. Sigue siempre tu AFM.","hint":"PARE: Power, Ailerons, Rudder, Elevator (potencia, alerones, timón, profundidad)."},"q095":{"q":"El efecto suelo durante el aterrizaje provoca:","options":["Más resistencia inducida – el avión baja más rápido","Menos resistencia inducida – el avión tiende a flotar","Mayor velocidad de pérdida","Solo un momento de picado"],"explain":"A menos de una envergadura del suelo, la resistencia inducida disminuye – el avión flota, sobre todo si va demasiado rápido.","hint":"Cerca del suelo los torbellinos de punta de ala son más débiles."},"q096":{"q":"La velocidad de maniobra (VA) con menor masa:","options":["Aumenta","Disminuye","Se mantiene igual","Es igual a VNE"],"explain":"VA disminuye con menor masa.","hint":"Un avión más ligero alcanza su carga límite a menor velocidad."},"q097":{"q":"El arco blanco del anemómetro indica:","options":["El rango de operación normal","El rango de operación de flaps","El rango de precaución","No exceder nunca"],"explain":"Arco blanco: rango de flaps. Verde: normal. Amarillo: precaución, solo en aire en calma. Línea roja: VNE.","hint":"El color del arco en el que puedes usar los flaps."},"q098":{"q":"El arco amarillo del anemómetro significa:","options":["Se pueden extender los flaps","Precaución – solo en aire en calma","Mejor planeo","Rango de pérdida"],"explain":"Rango de precaución: vuela solo en aire en calma, sin mandos bruscos.","hint":"Amarillo como una señal de advertencia."},"q099":{"q":"Con una hélice que gira en sentido horario (vista desde la cabina), en el despegue el avión tiende a:","options":["Guiñar a la izquierda – corregir con pedal derecho","Guiñar a la derecha – corregir con pedal izquierdo","Picar","No guiñar en absoluto"],"explain":"La estela de la hélice, el factor P y el par hacen guiñar el avión a la izquierda – hace falta pedal derecho. Comprueba cómo gira tu motor.","hint":"La estela de la hélice golpea el lado izquierdo de la cola."},"q100":{"q":"La resistencia inducida es máxima a:","options":["Alta velocidad","Baja velocidad / gran ángulo de ataque","Velocidad de crucero","Es constante"],"explain":"La resistencia inducida disminuye con la velocidad; la resistencia parásita aumenta con la velocidad.","hint":"La resistencia inducida es el precio de la sustentación con ángulo de ataque alto."},"q101":{"q":"Ordena los tiempos de un motor de pistón de cuatro tiempos.","items":["Admisión","Compresión","Explosión-expansión","Escape"],"explain":"Admisión → compresión → explosión-expansión (combustión) → escape.","hint":"Admisión – compresión – explosión – escape."},"q102":{"q":"¿Por qué los motores de pistón de avión tienen dos magnetos? (motor típico con magnetos)","options":["Para arrancar el motor más rápido","Redundancia y combustión más completa (dos bujías por cilindro)","Para alimentar la radio","Para cargar la batería"],"explain":"Dos sistemas de encendido independientes: seguridad si uno falla, mejor combustión con ambos.","hint":"Todo doble es más seguro, y quema mejor."},"q103":{"q":"Prueba de magnetos: ninguna caída de rpm al pasar a un solo magneto. ¿Qué puede significar? (motor típico con magnetos)","options":["Todo está perfecto","Puede que el magneto no esté a masa (cable P roto) – el motor podría arrancar si se mueve la hélice","La batería está descargada","La mezcla es demasiado pobre"],"explain":"Ninguna caída puede indicar una masa rota (cable P): el magneto sigue «vivo» incluso en OFF. Trata la hélice como peligrosa e infórmalo.","hint":"Un magneto que nunca se apaga es peligroso en tierra."},"q104":{"q":"Aplicas la calefacción del carburador. Las vueltas caen y luego suben lentamente. ¿Qué significa?","options":["Había hielo en el carburador y se está derritiendo","El motor se está sobrecalentando","Ha fallado el magneto","Normal – no hay hielo"],"explain":"El aire caliente es menos denso (caída de vueltas). Si el hielo se derrite, las vueltas vuelven a subir.","hint":"Primero la pérdida por el aire caliente, luego el hielo se derrite."},"q105":{"q":"¿Por qué empobreces la mezcla en el ascenso? (motor típico con control manual de mezcla)","options":["La densidad del aire disminuye – la mezcla se vuelve demasiado rica","Para enfriar el motor","Para aumentar la potencia por encima de todo","Nunca es necesario"],"explain":"Con la altitud hay menos aire para el mismo combustible: la mezcla se vuelve rica. Empobrece según el AFM.","hint":"Menos aire, el mismo combustible."},"q106":{"q":"¿Qué puede causar detonación?","options":["Mezcla demasiado rica","Mezcla demasiado pobre, temperatura alta de los cilindros o combustible con octanaje demasiado bajo","Poca potencia","Tiempo frío"],"explain":"Detonación = combustión explosiva descontrolada. Causas: mezcla pobre, temperaturas altas, combustible incorrecto.","hint":"Caliente y pobre es malo para el motor."},"q107":{"q":"El tubo pitot y su orificio de drenaje están obstruidos, la toma estática está abierta. En ascenso el anemómetro:","options":["Indica demasiado poco","Indica una velocidad creciente – actúa como un altímetro","Se mantiene constante y correcto","Indica cero"],"explain":"La presión total atrapada se mantiene mientras la presión estática baja – la velocidad indicada aumenta en el ascenso.","hint":"Presión atrapada en la línea pitot, presión estática exterior que baja."},"q108":{"q":"La toma estática está obstruida. ¿Qué indican el altímetro y el variómetro?","options":["Altímetro congelado, variómetro en cero","Ambos funcionan con normalidad","Altímetro demasiado alto, variómetro demasiado alto","Altímetro en cero"],"explain":"No cambia la presión estática: el altímetro se queda en el mismo valor, el variómetro indica cero. Usa la toma estática alternativa.","hint":"Ningún cambio de presión estática llega a los instrumentos."},"q109":{"q":"¿Cada cuánto deberías alinear el indicador de rumbo con la brújula magnética?","options":["Nunca","Aproximadamente cada 15 minutos, en vuelo recto y nivelado","Solo antes del despegue","Cada hora"],"explain":"La precesión giroscópica hace que el indicador de rumbo derive. Alinéalo aproximadamente cada 15 minutos cuando la brújula esté estable.","hint":"Los giróscopos derivan: un cuarto de hora."},"q110":{"q":"Hemisferio norte, rumbo este, aceleras. La brújula magnética indica:","options":["Un viraje aparente hacia el norte","Un viraje aparente hacia el sur","Ningún cambio","Gira sin parar"],"explain":"ANDS: Accelerate → North, Decelerate → South (en rumbos este/oeste).","hint":"Regla mnemotécnica inglesa: ANDS – Accelerate North, Decelerate South."},"q111":{"q":"La bola está desplazada a la derecha. ¿Qué haces?","options":["Pisar el pedal izquierdo","Pisar el pedal derecho","Empujar la palanca","Reducir potencia"],"explain":"«Pisa la bola»: pedal derecho para centrarla.","hint":"Pisa la bola."},"q112":{"q":"¿De qué color es el AVGAS 100LL?","options":["Rojo","Verde","Azul","Incoloro"],"explain":"El AVGAS 100LL está teñido de azul. El Jet A-1 es incoloro a pajizo.","hint":"El mismo color que muchos lagos en un día soleado."},"q113":{"q":"Síntoma temprano típico de la hipoxia:","options":["Dolor de oídos","Euforia y juicio alterado – a menudo sin darse cuenta","Hambre","Estornudos"],"explain":"La hipoxia llega sigilosamente: euforia, pensamiento más lento, malas decisiones – el piloto a menudo no lo nota.","hint":"Lo peligroso: te sientes bien."},"q114":{"q":"Part-NCO: ¿cuándo debe usar el piloto oxígeno suplementario?","options":["Siempre por encima de 8000 ft","Altitud de cabina por encima de 10 000 ft durante más de 30 minutos, y siempre por encima de 13 000 ft","Solo por encima de FL200","Nunca en vuelos no comerciales"],"explain":"Por encima de 10 000 ft durante más de 30 min y siempre por encima de 13 000 ft de altitud de cabina.","hint":"Dos umbrales: 10 000 ft durante un tiempo, 13 000 ft de inmediato."},"q115":{"q":"Una pista ascendente te da la sensación de:","options":["Estar demasiado bajo – tiendes a volar la aproximación demasiado alto","Estar demasiado alto – tiendes a volar la aproximación demasiado bajo","Nada especial","Ir demasiado rápido"],"explain":"Las pistas ascendentes (y estrechas) parecen indicar que vas alto – riesgo de aproximación demasiado baja.","hint":"Una pista ascendente hace que parezcas alto."},"q116":{"q":"Una pista más ancha de lo habitual te da la sensación de:","options":["Estar demasiado alto","Estar demasiado bajo – riesgo de recoger demasiado alto","Ir demasiado rápido","Nada especial"],"explain":"Una pista ancha parece más cercana – te sientes bajo y puedes recoger demasiado alto.","hint":"Una pista grande parece más cerca."},"q117":{"q":"Sospechas monóxido de carbono en la cabina (dolor de cabeza, somnolencia). ¿Qué haces?","options":["Encender la calefacción","Calefacción apagada, entradas de aire fresco abiertas, aterrizar lo antes posible","Subir más","Ignorarlo"],"explain":"El CO es inodoro y llega desde el escape a través de la calefacción. Calefacción apagada, aire fresco, aterrizar pronto.","hint":"Primero corta la fuente, luego aire fresco."},"q118":{"q":"Buena técnica de vigilancia exterior:","options":["Fijar la vista en un punto","Movimientos cortos de los ojos por sectores de unos 10°, cada uno de aproximadamente 1 segundo","Mirar solo al frente","Usar solo la pantalla de tráfico"],"explain":"El ojo necesita fijar la vista para detectar objetos. Explora el cielo sector por sector.","hint":"El ojo necesita detenerse para ver algo."},"q119":{"q":"Tras un viraje largo y constante nivelas las alas y te sientes inclinado hacia el otro lado. Esta ilusión se llama:","options":["Ilusión somatogravitatoria","The leans (ilusión de inclinación)","Black hole","Autocinesis"],"explain":"El oído interno se adapta a un viraje constante; al salir parece un viraje hacia el otro lado. Confía en los instrumentos/el horizonte.","hint":"Tu oído interno se ha acostumbrado al viraje."},"q120":{"q":"Una fuerte aceleración en el despegue (con mala visibilidad) puede sentirse como:","options":["Una actitud de morro abajo","Una actitud de morro arriba – riesgo de bajar el morro","Un viraje","Nada"],"explain":"Ilusión somatogravitatoria: la aceleración se siente como un encabritamiento.","hint":"La aceleración te empuja contra el asiento."},"q121":{"q":"¿Qué significa la «I» de la lista IMSAFE?","options":["Instruments","Illness (enfermedad)","Insurance","Identification"],"explain":"Illness – Medication – Stress – Alcohol – Fatigue – Eating/Emotion.","hint":"Lo primero que compruebas es tu propia salud."},"q146":{"q":"Esta mañana has buceado (sin paradas de descompresión). ¿Qué se recomienda normalmente antes de volar?","options":["Puedes volar enseguida","Esperar al menos 12 horas (al menos 24 horas tras inmersiones con paradas de descompresión)","Esperar 2 horas","Volar solo por debajo de 1000 ft"],"explain":"El nitrógeno disuelto en el cuerpo puede formar burbujas a menor presión de cabina (enfermedad descompresiva). Recomendación habitual: 12 h, o 24 h tras inmersiones con descompresión. Consulta a tu médico examinador (AME).","hint":"El nitrógeno disuelto necesita tiempo para salir del cuerpo."},"q147":{"q":"Hoy has donado sangre. ¿Qué se recomienda normalmente?","options":["Ninguna restricción","No volar como piloto durante al menos 24 horas","Volar solo con un pasajero","Esperar 2 horas"],"explain":"La pérdida de sangre puede causar mareos o desmayos, sobre todo en altura. Se suele recomendar no volar durante al menos 24 horas – consulta a tu médico examinador (AME).","hint":"Menos sangre = menos transporte de oxígeno."},"q148":{"q":"Estás resfriado y tienes la nariz tapada. ¿Cuál es el principal riesgo al volar?","options":["Ninguno","Dolor y lesiones en oídos o senos paranasales, sobre todo en el descenso, porque la presión no puede igualarse","Hipoxia a baja altura","Solo estornudos"],"explain":"Unas trompas de Eustaquio o senos tapados no pueden igualar la presión – dolor fuerte o barotrauma, sobre todo en el descenso. No vueles resfriado; los descongestionantes pueden dejar de hacer efecto en vuelo.","hint":"La presión tiene que igualarse, y los conductos tapados no pueden."},"q122":{"q":"Los vórtices de estela:","options":["Ascienden y se quedan donde se generaron","Descienden lentamente y derivan con el viento","Solo existen en crucero","Son más fuertes detrás de un avión ligero y rápido"],"explain":"Los vórtices descienden y derivan con el viento. Mantente por encima y a barlovento de la trayectoria del avión mayor.","hint":"Aire pesado girando detrás de las alas: ¿adónde va?"},"q123":{"q":"¿Cuándo es más fuerte la turbulencia de estela?","options":["Avión pesado, limpio y lento","Avión ligero y rápido","Avión con flaps totalmente extendidos a alta velocidad","Planeadores"],"explain":"Pesado, limpio (flaps recogidos) y lento – típico justo después del despegue y en la aproximación.","hint":"Pesado, limpio y lento significa ángulo de ataque alto."},"q124":{"q":"Aterrizaje después de un avión mayor en la misma pista:","options":["Tomar tierra antes de su punto de toma","Tomar tierra después de su punto de toma y mantenerse por encima de su senda de aproximación","Aterrizar lo antes posible","Aterrizar exactamente en el mismo punto"],"explain":"Mantente por encima de su trayectoria y aterriza más allá del punto donde tomó tierra.","hint":"Quédate por encima y aterriza después de su punto de toma."},"q125":{"q":"Frecuencia internacional de emergencia aeronáutica:","options":["118.000 MHz","121.500 MHz","123.450 MHz","406.000 MHz"],"explain":"121.500 MHz (frecuencia VHF de emergencia/escucha).","hint":"La frecuencia de guardia internacional en VHF."},"q126":{"q":"Los ELT modernos transmiten a los satélites en:","options":["Solo 121.5 MHz","406 MHz (con 121.5 MHz para la localización)","Solo 243 MHz","118 MHz"],"explain":"406 MHz a COSPAS-SARSAT, 121.5 MHz como señal de localización.","hint":"Los satélites escuchan en una frecuencia mucho más alta."},"q127":{"q":"Fallo de motor justo después del despegue a baja altura:","options":["Volver de inmediato a la pista","Bajar el morro, mejor planeo, aterrizar más o menos al frente","Ascender para ganar altura","Intentar volver a arrancar antes que nada"],"explain":"Vuela el avión: mejor planeo y aterriza al frente dentro de un ángulo pequeño. Dar la vuelta a baja altura suele terminar en pérdida.","hint":"Primero la velocidad: dar la vuelta a poca altura es la trampa clásica."},"q128":{"q":"Prioridades en cualquier situación anormal – ordénalas.","items":["Aviate (volar)","Navigate (navegar)","Communicate (comunicar)"],"explain":"Aviate – Navigate – Communicate, también conocido como Fly – Nav – Com: primero volar el avión, luego saber adónde ir, luego hablar.","hint":"Fly – Nav – Com."},"q129":{"q":"Ordena los tramos de un circuito de tránsito, empezando tras el despegue.","items":["Ascenso en el eje / tramo de salida (Upwind / Climb-out)","Tramo transversal (Crosswind)","Tramo de viento en cola (Downwind)","Tramo base (Base)","Final"],"explain":"Ascenso en el eje (Upwind) → transversal (Crosswind) → viento en cola (Downwind) → base (Base) → final.","hint":"Up, cross, down, base, final: salida, transversal, viento en cola, base, final."},"q130":{"q":"Salvo que se publique otra cosa, los circuitos de tránsito se vuelan:","options":["Por la derecha","Por la izquierda","En cualquier sentido","Solo con aproximación directa"],"explain":"El estándar es por la izquierda. Consulta siempre la VAC – muchos aeródromos suizos tienen circuitos por la derecha para algunas pistas.","hint":"En la mayoría de los aviones los pilotos se sientan a la izquierda."},"q131":{"q":"La pista «26» significa que su orientación es de aproximadamente:","options":["026° verdaderos","260° magnéticos","260° verdaderos","026° magnéticos"],"explain":"Número de pista = orientación magnética redondeada a 10°, dividida por 10.","hint":"Añade un cero; los números de pista son magnéticos."},"q132":{"q":"«WILCO» significa:","options":["He recibido su mensaje","He comprendido su mensaje y lo cumpliré","Repita","Espere"],"explain":"Will comply – lo he entendido y lo haré.","hint":"WILl COmply: cumpliré."},"q133":{"q":"«ROGER» significa:","options":["Sí","Lo cumpliré","He recibido toda su última transmisión","Repita"],"explain":"Roger = recibido. No es una respuesta a una pregunta ni una colación.","hint":"Solo recibido, nada más."},"q134":{"q":"«AFFIRM» significa:","options":["Sí","No","Lo cumpliré","Espere"],"explain":"Affirm = sí. Negative = no.","hint":"Affirm suena como «affirmative» (afirmativo)."},"q135":{"q":"Legibilidad 5 significa:","options":["Ilegible","Legible a ratos","Legible con dificultad","Perfectamente legible"],"explain":"1 ilegible – 2 a ratos – 3 con dificultad – 4 legible – 5 perfectamente legible.","hint":"El número más alto de la escala."},"q136":{"q":"¿Qué elementos deben colacionarse siempre?","options":["La información de viento","Pista, reglaje altimétrico, código SSR y autorizaciones","La información de tránsito","Los informes meteorológicos"],"explain":"Pista en uso, autorizaciones, reglajes altimétricos, códigos SSR, instrucciones de nivel/rumbo/velocidad (y cambios de frecuencia).","hint":"Todo lo que cambia adónde vas o cómo ajustas los instrumentos."},"q137":{"q":"«MAYDAY» se usa para:","options":["Urgencia – un problema pero sin peligro inmediato","Socorro – peligro grave e inminente, se requiere ayuda inmediata","Prueba de radio","Notificación de posición"],"explain":"MAYDAY = socorro. PAN PAN = urgencia.","hint":"Del francés «m'aider»: ayúdame."},"q138":{"q":"Ordena estas categorías de mensajes por prioridad (la más alta primero).","items":["Socorro","Urgencia","Seguridad de vuelo","Meteorología"],"explain":"Socorro → urgencia → (radiogoniometría) → seguridad de vuelo → meteorología → regularidad de los vuelos.","hint":"Primero la vida, luego los problemas urgentes, luego la seguridad, luego el tiempo."},"q139":{"q":"«SQUAWK IDENT» significa:","options":["Poner el código 7000","Pulsar el botón IDENT del transpondedor","Apagar el transpondedor","Decir tu indicativo"],"explain":"Activar la función de identificación especial de posición (IDENT).","hint":"El botón que hace destacar tu eco en la pantalla del radar."},"q140":{"q":"¿Qué hora se usa en las comunicaciones radio aeronáuticas?","options":["Hora local","UTC","Hora del aeródromo de salida","Cualquier hora"],"explain":"Siempre se usa UTC.","hint":"Los pilotos de todo el mundo usan el mismo reloj."}}`),r={version:e,categories:t,questions:n};export{t as categories,r as default,n as questions,e as version};